let appModalBackdropCounter = 0;

function dispatchModalEvent(modalEl, eventName, relatedTarget = null) {
  const modalEvent = new CustomEvent(eventName, {
    bubbles: true,
    cancelable: true,
  });
  Object.defineProperty(modalEvent, "relatedTarget", {
    value: relatedTarget,
    enumerable: true,
  });
  modalEl.dispatchEvent(modalEvent);
  return modalEvent;
}

function showModalFallback(modalEl, relatedTarget = null) {
  if (!modalEl) return;

  const beforeShow = dispatchModalEvent(
    modalEl,
    "show.bs.modal",
    relatedTarget,
  );
  if (beforeShow.defaultPrevented) return;

  if (!modalEl.classList.contains("show")) {
    modalEl.classList.add("show");
    modalEl.style.display = "block";
    modalEl.removeAttribute("aria-hidden");
    modalEl.setAttribute("aria-modal", "true");

    const backdrop = document.createElement("div");
    const backdropId = `app-modal-backdrop-${++appModalBackdropCounter}`;
    backdrop.id = backdropId;
    backdrop.className = "modal-backdrop fade show";
    backdrop.setAttribute("data-app-modal-backdrop", "true");
    document.body.appendChild(backdrop);
    modalEl.setAttribute("data-app-backdrop-id", backdropId);
    document.body.classList.add("modal-open");
  }

  dispatchModalEvent(modalEl, "shown.bs.modal", relatedTarget);
}

function hideModalFallback(modalEl) {
  if (!modalEl) return;

  const beforeHide = dispatchModalEvent(modalEl, "hide.bs.modal");
  if (beforeHide.defaultPrevented) return;

  modalEl.classList.remove("show");
  modalEl.style.display = "none";
  modalEl.setAttribute("aria-hidden", "true");
  modalEl.removeAttribute("aria-modal");

  const backdropId = modalEl.getAttribute("data-app-backdrop-id");
  if (backdropId) {
    document.getElementById(backdropId)?.remove();
    modalEl.removeAttribute("data-app-backdrop-id");
  }

  if (!document.querySelector(".modal.show")) {
    document.body.classList.remove("modal-open");
  }

  dispatchModalEvent(modalEl, "hidden.bs.modal");
}

function getModalController(modalEl) {
  if (!modalEl) return null;

  if (window.bootstrap?.Modal) {
    const instance = window.bootstrap.Modal.getOrCreateInstance(modalEl);
    return {
      show: (relatedTarget = null) => instance.show(relatedTarget),
      hide: () => instance.hide(),
    };
  }

  return {
    show: (relatedTarget = null) => showModalFallback(modalEl, relatedTarget),
    hide: () => hideModalFallback(modalEl),
  };
}

function dispatchCollapseEvent(collapseEl, eventName) {
  const collapseEvent = new CustomEvent(eventName, {
    bubbles: true,
    cancelable: true,
  });
  collapseEl.dispatchEvent(collapseEvent);
  return collapseEvent;
}

function setCollapseTriggerState(collapseEl, isExpanded) {
  if (!collapseEl?.id) return;

  const selectors = [
    `[data-bs-target="#${collapseEl.id}"]`,
    `[aria-controls="${collapseEl.id}"]`,
  ];

  selectors.forEach((selector) => {
    document.querySelectorAll(selector).forEach((trigger) => {
      trigger.setAttribute("aria-expanded", isExpanded ? "true" : "false");
      if (!trigger.classList.contains("collapsed")) {
        if (!isExpanded) trigger.classList.add("collapsed");
      } else if (isExpanded) {
        trigger.classList.remove("collapsed");
      }
    });
  });
}

function showCollapseFallback(collapseEl) {
  if (!collapseEl) return;
  if (collapseEl.classList.contains("show")) return;

  const beforeShow = dispatchCollapseEvent(collapseEl, "show.bs.collapse");
  if (beforeShow.defaultPrevented) return;

  const parentSelector = collapseEl.getAttribute("data-bs-parent");
  if (parentSelector) {
    document
      .querySelectorAll(`${parentSelector} .accordion-collapse.show`)
      .forEach((openEl) => {
        if (openEl !== collapseEl) {
          hideCollapseFallback(openEl);
        }
      });
  }

  collapseEl.classList.add("show");
  setCollapseTriggerState(collapseEl, true);
  dispatchCollapseEvent(collapseEl, "shown.bs.collapse");
}

function hideCollapseFallback(collapseEl) {
  if (!collapseEl) return;
  if (!collapseEl.classList.contains("show")) return;

  const beforeHide = dispatchCollapseEvent(collapseEl, "hide.bs.collapse");
  if (beforeHide.defaultPrevented) return;

  collapseEl.classList.remove("show");
  setCollapseTriggerState(collapseEl, false);
  dispatchCollapseEvent(collapseEl, "hidden.bs.collapse");
}

function getCollapseController(collapseEl) {
  if (!collapseEl) return null;

  if (window.bootstrap?.Collapse) {
    const instance = window.bootstrap.Collapse.getOrCreateInstance(collapseEl, {
      toggle: false,
    });
    return {
      show: () => instance.show(),
      hide: () => instance.hide(),
    };
  }

  return {
    show: () => showCollapseFallback(collapseEl),
    hide: () => hideCollapseFallback(collapseEl),
  };
}

function dispatchTabEvent(tabEl, eventName, relatedTarget = null) {
  const tabEvent = new CustomEvent(eventName, {
    bubbles: true,
    cancelable: true,
  });
  Object.defineProperty(tabEvent, "relatedTarget", {
    value: relatedTarget,
    enumerable: true,
  });
  tabEl.dispatchEvent(tabEvent);
  return tabEvent;
}

function getTabTargetSelector(tabEl) {
  if (!tabEl) return null;
  return tabEl.getAttribute("data-bs-target") || tabEl.getAttribute("href");
}

function showTabFallback(tabEl) {
  if (!tabEl) return;

  const tabList = tabEl.closest('[role="tablist"]') || tabEl.closest(".nav");
  const tabTriggers = tabList
    ? Array.from(tabList.querySelectorAll('[data-bs-toggle="pill"]'))
    : [tabEl];

  const activeTab = tabTriggers.find((tabTrigger) =>
    tabTrigger.classList.contains("active"),
  );

  const targetSelector = getTabTargetSelector(tabEl);
  const targetPane = targetSelector
    ? document.querySelector(targetSelector)
    : null;

  if (
    activeTab === tabEl &&
    (!targetPane || targetPane.classList.contains("show"))
  ) {
    return;
  }

  if (activeTab) {
    const beforeHide = dispatchTabEvent(activeTab, "hide.bs.tab", tabEl);
    if (beforeHide.defaultPrevented) return;
  }

  const beforeShow = dispatchTabEvent(tabEl, "show.bs.tab", activeTab || null);
  if (beforeShow.defaultPrevented) return;

  tabTriggers.forEach((tabTrigger) => {
    const paneSelector = getTabTargetSelector(tabTrigger);
    const pane = paneSelector ? document.querySelector(paneSelector) : null;

    tabTrigger.classList.remove("active");
    tabTrigger.setAttribute("aria-selected", "false");
    if (pane) {
      pane.classList.remove("active", "show");
    }
  });

  tabEl.classList.add("active");
  tabEl.setAttribute("aria-selected", "true");
  if (targetPane) {
    targetPane.classList.add("active", "show");
  }

  if (activeTab) {
    dispatchTabEvent(activeTab, "hidden.bs.tab", tabEl);
  }
  dispatchTabEvent(tabEl, "shown.bs.tab", activeTab || null);
}

function getTabController(tabEl) {
  if (!tabEl) return null;

  if (window.bootstrap?.Tab) {
    const instance = window.bootstrap.Tab.getOrCreateInstance(tabEl);
    return {
      show: () => instance.show(),
    };
  }

  return {
    show: () => showTabFallback(tabEl),
  };
}

if (!window.bootstrap?.Tab) {
  document.addEventListener("click", (event) => {
    const tabTrigger = event.target.closest('[data-bs-toggle="pill"]');
    if (!tabTrigger) return;

    event.preventDefault();
    getTabController(tabTrigger)?.show();
  });
}

