function renderFavoritesList() {
  const listContainer = document.getElementById("favorites-list");
  if (!listContainer) return;

  favorites = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}") || {};
  const keys = Object.keys(favorites);

  if (keys.length === 0) {
    listContainer.innerHTML =
      '<div class="text-center py-4 text-muted"><p class="mb-0">No favorites saved yet.</p><small>Tap the star icon on any talk or session to save it here.</small></div>';
    return;
  }

  let favItems = keys.map((key) => ({
    key: key,
    data: favorites[key] || {},
  }));

  favItems.sort((a, b) => {
    const timeA = a.data.time ? new Date(a.data.time).getTime() : 0;
    const timeB = b.data.time ? new Date(b.data.time).getTime() : 0;
    return timeA - timeB;
  });

  listContainer.innerHTML = "";

  favItems.forEach((item) => {
    const [type, id] = item.key.split(":");
    const data = item.data;
    const isFav = !!favorites[`${type}:${id}`];
    const starImg = isFav ? "./star-fill.svg" : "./star.svg";

    const cardElement = document.createElement("div");
    cardElement.className = "card rounded-0 mb-2 shadow-sm";

    let content = "";
    let formattedTime = "";

    if (data.time) {
      const dateObj = new Date(data.time);
      if (!isNaN(dateObj.getTime())) {
        formattedTime =
          dateObj.toLocaleDateString("en-US", {
            weekday: "short",
            month: "short",
            day: "numeric",
          }) +
          " " +
          dateObj.toLocaleTimeString("en-US", {
            hour: "2-digit",
            minute: "2-digit",
          });
      } else {
        formattedTime = data.time;
      }
    }

    let modalAttributes =
      type === "talk"
        ? `role="button" tabindex="0" data-bs-toggle="modal" data-bs-target="#globalTalkModal" data-id="${id}"`
        : "";

    content += `<div class="flex-grow-1 text-start" ${modalAttributes}>`;
    content += `  <h6 class="${type === "talk" ? "mb-1 text-primary fw-bold" : "mb-1 text-success fw-bold"}">${data.title || "Untitled"}</h6>`;

    if (formattedTime) {
      content += `  <p class="mb-0 small text-muted"><img src="./calendar.svg" alt="Calendar" style="width: 14px; margin-right: 4px;" /> ${formattedTime}</p>`;
    }
    if (data.location) {
      content += `  <p class="mb-0 small text-muted"><img src="./geo-alt.svg" alt="Location" style="width: 14px; margin-right: 4px;" /> ${data.location}</p>`;
    }
    content += `</div>`;

    content += `<div>`;
    content += `  <button type="button" class="fav-btn btn btn-link p-0 ms-3"
                            data-type="${type}"
                            data-id="${id}"
                            data-time="${data.time || ""}"
                            data-location="${data.location || ""}"
                            data-title="${(data.title || "").replace(/"/g, "&quot;")}"
                            title="Favorite">
                            <img src="${starImg}" alt="Favorite" />
                          </button>`;
    content += `</div>`;

    const cardBody = document.createElement("div");
    cardBody.className =
      "card-body d-flex justify-content-between align-items-center p-3";

    cardBody.innerHTML = content;
    cardElement.appendChild(cardBody);
    listContainer.appendChild(cardElement);
  });
}

function updateFavoriteIcons(type, id) {
  const key = `${type}:${id}`;
  const isFav = !!favorites[key];
  const buttons = document.querySelectorAll(
    `.fav-btn[data-type="${type}"][data-id="${id}"]`,
  );
  buttons.forEach((btn) => {
    const img = btn.querySelector("img");
    if (img) {
      img.src = isFav ? "./star-fill.svg" : "./star.svg";
    }
  });
}

document.addEventListener("DOMContentLoaded", () => {
  showScheduleView();
  updatePlatformIcons();

  document.querySelectorAll(".fav-btn").forEach((btn) => {
    updateFavoriteIcons(btn.dataset.type, btn.dataset.id);
  });

  const searchInput = document.getElementById("search-input");
  const tabElements = document.querySelectorAll(
    '#pills-tab button[data-bs-toggle="pill"]',
  );

  tabElements.forEach((tab) => {
    tab.addEventListener("shown.bs.tab", function () {
      if (searchInput) {
        searchInput.placeholder = "Search talks by title or abstract...";
      }
    });
  });

  // Global Favorite Click Handling
  document.body.addEventListener("click", (e) => {
    const btn = e.target.closest(".fav-btn");
    if (!btn) return;

    const id = btn.dataset.id;
    const type = btn.dataset.type;
    if (!id || !type) return;

    const key = `${type}:${id}`;
    const talkData = getTalkById(id);

    let labelText = btn.dataset.title;
    if (!labelText && type === "talk" && talkData) {
      labelText = talkData.title;
    }
    if (!labelText) {
      const parent = btn.closest(".accordion-header, .d-flex, .modal-content");
      if (parent) {
        const titleEl = parent.querySelector(
          ".fw-bold, button.pseudo-btn, h6, strong",
        );
        if (titleEl) labelText = titleEl.innerText.trim();
      }
    }
    if (!labelText) labelText = "Untitled Item";

    labelText = labelText.split("\n")[0];

    if (favorites[key]) {
      delete favorites[key];
    } else {
      favorites[key] = {
        title: labelText,
        time: btn.dataset.time || (talkData ? talkData.startdatetime : ""),
        location: btn.dataset.location || (talkData ? talkData.location : ""),
        timestamp: new Date().toISOString(),
      };
    }

    localStorage.setItem(STORAGE_KEY, JSON.stringify(favorites));
    updateFavoriteIcons(type, id);

    const favsView = document.getElementById("app-favorites-view");
    if (favsView && favsView.style.display !== "none") {
      renderFavoritesList();
    }
  });

  // Bottom Navigation Listeners
  document
    .getElementById("btn-nav-schedule")
    ?.addEventListener("click", (e) => {
      e.preventDefault();
      showScheduleView();
    });

  document.getElementById("btn-nav-authors")?.addEventListener("click", (e) => {
    e.preventDefault();
    showAuthorsView();
  });

  document
    .getElementById("btn-nav-favorites")
    ?.addEventListener("click", (e) => {
      e.preventDefault();
      showFavoritesView();
    });

  document.getElementById("btn-nav-map")?.addEventListener("click", (e) => {
    e.preventDefault();
    showMapView();
  });

  document
    .getElementById("btn-export-favorites")
    ?.addEventListener("click", async () => {
      const storedFavs =
        JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}") || {};
      const keys = Object.keys(storedFavs);
      const talkKeys = keys.filter((key) => key.startsWith("talk:"));

      if (talkKeys.length === 0) {
        alert("You don't have any favorited talks to export yet!");
        return;
      }

      let compiledTalks = talkKeys.map((key) => {
        const [_, id] = key.split(":");
        const talkData = getTalkById(id);
        const favItem = storedFavs[key] || {};

        const rawAbstract = talkData
          ? talkData.abstract || talkData.description || talkData.content
          : "";

        return {
          time: talkData ? talkData.startdatetime : favItem.time || "",
          metaTime: talkData
            ? `${talkData.day || ""}, ${talkData.start_time || ""}`
            : "",
          location: talkData ? talkData.location : favItem.location || "",
          formattedContent: rawAbstract
            ? convertAbstractToPlainText(rawAbstract)
            : `ðŸ“Œ ${favItem.title || "Talk"}`,
        };
      });

      compiledTalks.sort((a, b) => new Date(a.time) - new Date(b.time));

      let exportText =
        "Advanced Accelerator Concepts 2026 - My Saved Talks & Abstracts\n";
      exportText += "========================================\n\n";

      compiledTalks.forEach((talk) => {
        exportText += talk.formattedContent + "\n";
        if (talk.metaTime)
          exportText += `â° SCHEDULED TIME: ${talk.metaTime}\n`;
        if (talk.location) exportText += `ðŸ“ LOCATION: ${talk.location}\n`;
        exportText += "\n----------------------------------------\n\n";
      });

      if (navigator.share) {
        try {
          await navigator.share({
            title:
              "My Advanced Accelerator Concepts 2026 Presentation Abstracts",
            text: exportText,
          });
        } catch (err) {
          if (err.name !== "AbortError") {
            console.error("Native OS web share pipeline failed:", err);
          }
        }
      } else {
        await copyToClipboardFallback(
          exportText,
          document.getElementById("btn-export-favorites"),
        );
      }
    });
});

// On-Demand Author Rendering
let authorsRendered = false;

function renderAuthorsSkeleton() {
  if (authorsRendered) return;
  const container = document.getElementById("accordion-authors");
  if (!container) return;

  const fragment = document.createDocumentFragment();

  const sortedAuthors = Object.values(authorIndex || {})
    .filter((author) => {
      if (!author) return false;
      const fullName =
        author.firstName || author.familyName
          ? `${author.firstName || ""} ${author.familyName || ""}`.trim()
          : (author.name || author.full_name || "").trim();
      return fullName.length > 0;
    })
    .sort((a, b) => {
      const lastNameCompare = (a?.familyName || a?.name || "").localeCompare(
        b?.familyName || b?.name || "",
      );
      if (lastNameCompare !== 0) return lastNameCompare;
      return (a?.firstName || "").localeCompare(b?.firstName || "");
    });

  sortedAuthors.forEach((author) => {
    const fullName =
      author.firstName || author.familyName
        ? `${author.firstName || ""} ${author.familyName || ""}`.trim()
        : (author.name || author.full_name || "").trim();
    const authorId = author.person_id || author.id;
    if (!authorId) return;

    const item = document.createElement("div");
    item.className = "accordion-item";
    item.setAttribute("id", `author-row-${authorId}`);
    item.setAttribute("data-id", authorId);
    item.setAttribute("data-name", fullName);

    item.innerHTML = `
    <h2 class="accordion-header d-flex justify-content-between align-items-center">
        <button class="accordion-button collapsed" type="button" data-bs-toggle="collapse"
            data-bs-target="#collapse${authorId}" aria-expanded="false"
            aria-controls="collapse${authorId}" data-author-id="${authorId}">
            <div class="text-start">
                <strong>${fullName}</strong><br />
                <small class="text-muted fw-normal">${author.affiliation || ""}</small>
            </div>
        </button>
        <button type="button" class="btn btn-link p-0 text-muted me-3 share-btn" data-route="author" data-id="${authorId}" data-title="${fullName}" title="Share Author">
            <img class="share-icon" src="${shareIconSrc}" alt="Share" />
        </button>
    </h2>
    <div id="collapse${authorId}" class="accordion-collapse collapse"
        data-bs-parent="#accordion-authors">
        <div class="accordion-body" id="author-body-${authorId}">
            <div class="text-center py-2">
                <div class="spinner-border spinner-border-sm text-muted" role="status"></div>
            </div>
        </div>
    </div>
`;
    fragment.appendChild(item);
  });

  container.innerHTML = "";
  container.appendChild(fragment);
  authorsRendered = true;
}

// Lazy-load author details
document
  .getElementById("accordion-authors")
  ?.addEventListener("show.bs.collapse", (e) => {
    const button =
      e.target.previousElementSibling?.querySelector(".accordion-button");
    if (!button) return;

    const authorId = button.getAttribute("data-author-id");
    const bodyZone = document.getElementById(`author-body-${authorId}`);

    if (bodyZone && bodyZone.querySelector(".spinner-border")) {
      const author =
        (authorIndex || {})[authorId] ||
        Object.values(authorIndex || {}).find(
          (a) => String(a?.person_id || a?.id) === String(authorId),
        );
      if (
        !author ||
        !author.presentations ||
        author.presentations.length === 0
      ) {
        bodyZone.innerHTML =
          '<p class="text-muted small mb-0">No sessions listed.</p>';
        return;
      }

      let html = "";

      if (author.email) {
        html += `
        <div class="mb-3 border-bottom pb-2">
            <a href="mailto:${author.email}" class="btn btn-sm btn-outline-secondary d-inline-flex align-items-center">
                <i class="bi bi-envelope me-2"></i> Contact Author (${author.email})
            </a>
        </div>
    `;
      }

      author.presentations.forEach((talkId) => {
        const talk = getTalkById(talkId);
        if (!talk) return;

        const safeTitle = (talk.title || "").replace(/"/g, "&quot;");
        const safeAbstract = (
          talk.abstract ||
          talk.description ||
          talk.content ||
          ""
        ).replace(/"/g, "&quot;");
        const dayTimeLoc = `${talk.day || ""}, ${talk.start_time || ""}${talk.location ? ". " + talk.location : ""}`;

        html += `
        <div class="d-flex align-items-center mb-2">
            <button type="button" class="btn btn-light text-start author-talk-btn"
                data-bs-toggle="modal" data-bs-target="#globalTalkModal" data-id="${talk.id}" data-abstract="${safeAbstract}">
                ${dayTimeLoc}. <strong>${talk.title}</strong>
            </button>
            <button type="button" class="btn btn-link p-0 text-muted ms-2 share-btn" data-route="talk" data-id="${talk.id}" data-title="${safeTitle}" title="Share Talk">
                <img class="share-icon" src="${shareIconSrc}" alt="Share" />
            </button>
            <button type="button" class="fav-btn" data-type="talk" data-id="${talk.id}" data-title="${safeTitle}" title="Favorite">
                <img src="./star.svg" alt="Favorite" />
            </button>
        </div>
    `;
      });
      bodyZone.innerHTML = html;

      author.presentations.forEach((talkId) => {
        updateFavoriteIcons("talk", talkId);
      });
    }
  });

document.addEventListener("DOMContentLoaded", () => {
  const globalModal = document.getElementById("globalTalkModal");
  if (globalModal) {
    globalModal.addEventListener("show.bs.modal", function (event) {
      const button = event.relatedTarget;
      const id = button
        ? button.getAttribute("data-id")
        : globalModal.dataset.activeTalkId;

      if (id && window.location.hash !== `#/talk/${id}`) {
        window.location.hash = `#/talk/${id}`;
      }

      const talkData = getTalkById(id);
      const metaNode = document.getElementById("modal-talk-meta");
      const abstractNode = document.getElementById("modal-talk-abstract");
      const modalFavBtn = document.getElementById("modal-fav-btn");
      const modalCopyBtn = document.getElementById("modal-copy-btn");

      const rawAbstract =
        (talkData &&
          (talkData.abstract || talkData.description || talkData.content)) ||
        (button ? button.getAttribute("data-abstract") : "") ||
        "";

      if (talkData) {
        if (metaNode)
          metaNode.textContent = `${talkData.day || ""}, ${talkData.start_time || ""}${talkData.location ? ". " + talkData.location : ""}`;

        modalFavBtn?.setAttribute("data-id", talkData.id);
        modalFavBtn?.setAttribute("data-title", talkData.title || "");
        modalFavBtn?.setAttribute("data-time", talkData.startdatetime || "");
        modalFavBtn?.setAttribute("data-location", talkData.location || "");

        modalCopyBtn?.setAttribute("data-id", talkData.id);
        modalCopyBtn?.setAttribute("data-title", talkData.title || "");
      } else if (button) {
        if (metaNode)
          metaNode.textContent = button.getAttribute("data-meta") || "";

        modalFavBtn?.setAttribute("data-id", id);
        modalFavBtn?.setAttribute(
          "data-title",
          button.getAttribute("data-title") || "",
        );
        modalFavBtn?.setAttribute(
          "data-time",
          button.getAttribute("data-time") ||
            button.getAttribute("data-datetime") ||
            "",
        );
        modalFavBtn?.setAttribute(
          "data-location",
          button.getAttribute("data-location") || "",
        );

        modalCopyBtn?.setAttribute("data-id", id);
        modalCopyBtn?.setAttribute(
          "data-title",
          button.getAttribute("data-title") || "",
        );
      }

      if (abstractNode) {
        abstractNode.innerHTML = rawAbstract
          ? rawAbstract
          : "<p>Abstract not provided.</p>";
      }

      updateFavoriteIcons("talk", id);
    });
  }

  const searchInput = document.getElementById("search-input");
  const searchResults = document.getElementById("search-results");

  if (searchInput && searchResults) {
    const clearBtn = document.getElementById("clear-search");
    searchInput.addEventListener("input", (e) => {
      const query = e.target.value.toLowerCase().trim();
      searchResults.innerHTML = "";

      // Toggle visibility of the clear button
      if (clearBtn) {
        clearBtn.style.display = query.length > 0 ? "inline-block" : "none";
      }

      if (query.length < 2) return;

      const isAuthorsView = document
        .getElementById("pills-authors")
        ?.classList.contains("active");
      let results = [];

      if (isAuthorsView) {
        results = Object.values(authorIndex || {}).filter((author) => {
          if (!author) return false;
          const fullName =
            `${author.firstName || author.name || ""} ${author.familyName || ""}`.toLowerCase();
          const affiliation = (author.affiliation || "").toLowerCase();
          return fullName.includes(query) || affiliation.includes(query);
        });
      } else {
        results = Object.values(talkIndex || {}).filter(
          (talk) =>
            talk &&
            ((talk.title && talk.title.toLowerCase().includes(query)) ||
              (talk.abstract && talk.abstract.toLowerCase().includes(query)) ||
              (talk.id && talk.id.toString().toLowerCase().includes(query))),
        );
      }

      results.forEach((item) => {
        const resultItem = document.createElement("button");
        resultItem.className =
          "list-group-item list-group-item-action d-flex justify-content-between align-items-center";

        resultItem.dataset.targetId = item.person_id || item.id;
        resultItem.dataset.isAuthor = isAuthorsView ? "true" : "false";

        if (isAuthorsView) {
          const name =
            `${item.firstName || item.name || ""} ${item.familyName || ""}`.trim();
          resultItem.innerHTML = `<span class="text-start">${name}</span>`;
        } else {
          resultItem.innerHTML = `<span class="text-start">${item.day || ""} ${item.start_time || ""} ${item.location || ""}: ${item.title || ""}</span>`;
        }
        searchResults.appendChild(resultItem);
      });
    });

    searchResults.addEventListener("click", (e) => {
      const btn = e.target.closest("button");
      if (!btn || !searchResults.contains(btn)) return;

      const targetId = btn.dataset.targetId;
      const isAuthor = btn.dataset.isAuthor === "true";

      if (isAuthor) {
        const element = document.getElementById(`collapse${targetId}`);
        if (element) {
          getCollapseController(element)?.show();
          setTimeout(() => {
            element
              .closest(".accordion-item")
              ?.scrollIntoView({ behavior: "smooth", block: "start" });
          }, 300);
        }
      } else {
        const originalBtn = document.querySelector(
          `button[data-id="${targetId}"][data-bs-target="#globalTalkModal"]`,
        );
        const modalController = getModalController(globalModal);

        if (originalBtn) {
          modalController?.show(originalBtn);
        } else {
          globalModal.dataset.activeTalkId = targetId;
          modalController?.show();
        }
      }
    });
  }

  document.getElementById("clear-search")?.addEventListener("click", () => {
    if (searchInput) {
      searchInput.value = "";
      searchInput.dispatchEvent(new Event("input"));
    }
    if (searchResults) {
      searchResults.innerHTML = "";
    }
  });
});

// Sync Hash Routing
function handleRouting() {
  const hash = window.location.hash;
  if (!hash) return;

  const parts = hash.split("/");
  if (parts.length < 3) return;

  const routeType = parts[1];
  const id = parts[2];

  if (routeType === "talk") {
    const globalModal = document.getElementById("globalTalkModal");
    if (globalModal) {
      const originalBtn = document.querySelector(
        `button[data-id="${id}"][data-bs-target="#globalTalkModal"]`,
      );
      const modalController = getModalController(globalModal);

      if (originalBtn) {
        modalController?.show(originalBtn);
      } else {
        globalModal.dataset.activeTalkId = id;
        modalController?.show();
      }
    }
  } else if (routeType === "session") {
    showScheduleView();

    const element = document.querySelector(
      `.tab-content .tab-pane:not(#pills-authors) #collapse${id}`,
    );
    if (element) {
      // Activate parent nested tabs up the DOM tree
      let current = element.parentElement;
      while (current && !current.classList.contains("container-fluid")) {
        if (current.classList.contains("tab-pane")) {
          const tabTrigger = document.querySelector(
            `button[data-bs-target="#${current.id}"]`,
          );
          if (tabTrigger) getTabController(tabTrigger)?.show();
        }
        current = current.parentElement;
      }

      getCollapseController(element)?.show();
      setTimeout(() => {
        element
          .closest(".accordion-item")
          ?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 300);
    }
  } else if (routeType === "author") {
    showAuthorsView();

    const element = document.querySelector(`#accordion-authors #collapse${id}`);
    if (element) {
      getCollapseController(element)?.show();
      setTimeout(() => {
        element
          .closest(".accordion-item")
          ?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 300);
    }
  }
}

window.addEventListener("hashchange", handleRouting);
document.addEventListener("DOMContentLoaded", () => {
  setTimeout(handleRouting, 100);
});

document.body.addEventListener("show.bs.collapse", function (event) {
  const collapseEl = event.target;
  if (!collapseEl.id || !collapseEl.id.startsWith("collapse")) return;

  const id = collapseEl.id.replace("collapse", "");

  if (collapseEl.closest("#accordion-authors")) {
    if (window.location.hash !== `#/author/${id}`)
      window.location.hash = `#/author/${id}`;
  } else {
    if (window.location.hash !== `#/session/${id}`)
      window.location.hash = `#/session/${id}`;
  }
});

document.body.addEventListener("hide.bs.collapse", function (event) {
  const collapseEl = event.target;
  if (!collapseEl.id || !collapseEl.id.startsWith("collapse")) return;

  const id = collapseEl.id.replace("collapse", "");
  if (
    window.location.hash === `#/session/${id}` ||
    window.location.hash === `#/author/${id}`
  ) {
    window.location.hash = "";
  }
});

// QR Scanner Handlers
let html5QrScanner = null;

document.getElementById("btn-scan-qr")?.addEventListener("click", () => {
  const qrModalEl = document.getElementById("qrScannerModal");
  if (qrModalEl) {
    const scannerModal = getModalController(qrModalEl);
    scannerModal?.show();
  }
});

document
  .getElementById("qrScannerModal")
  ?.addEventListener("shown.bs.modal", () => {
    html5QrScanner = new Html5Qrcode("qr-video-reader");
    const config = { fps: 10, qrbox: { width: 250, height: 250 } };

    html5QrScanner
      .start(
        { facingMode: "environment" },
        config,
        (decodedText) => {
          try {
            const url = decodedText.includes("#") ? new URL(decodedText) : null;
            const hashValue = url ? url.hash : decodedText;

            if (hashValue && hashValue.startsWith("#/")) {
              html5QrScanner.stop().then(() => {
                const qrModalEl = document.getElementById("qrScannerModal");
                if (qrModalEl) getModalController(qrModalEl)?.hide();
                window.location.hash = hashValue;
              });
            }
          } catch (err) {
            console.error("Malformed QR data payload parsed.", err);
          }
        },
        () => {},
      )
      .catch((err) =>
        console.error(
          "Camera access failed or rejected by system settings.",
          err,
        ),
      );
  });

document
  .getElementById("qrScannerModal")
  ?.addEventListener("hide.bs.modal", () => {
    if (html5QrScanner && html5QrScanner.isScanning) {
      html5QrScanner
        .stop()
        .catch((err) =>
          console.error("Error killing video track context.", err),
        );
    }
  });

async function copyToClipboardFallback(textToCopy, btn) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(textToCopy);
    } else {
      const textarea = document.createElement("textarea");
      textarea.value = textToCopy;
      textarea.style.position = "fixed";
      textarea.style.opacity = "0";
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
    }

    const img = btn?.querySelector("img");
    if (img) {
      const originalSrc = img.src;
      img.src = "./link.svg";
      setTimeout(() => {
        img.src = originalSrc;
      }, 1000);
    }
  } catch (err) {
    console.error("Clipboard copy fallback failed:", err);
  }
}

document.body.addEventListener("click", async (e) => {
  const btn = e.target.closest(".share-btn, .copy-btn");
  if (!btn) return;

  e.preventDefault();
  e.stopPropagation();

  const route = btn.dataset.route;
  const id = btn.dataset.id;
  if (!route || !id) return;

  let plainTextTitle = btn.dataset.title || "";
  let shareText = "";

  if (route === "talk") {
    const talkData = getTalkById(id);
    plainTextTitle = plainTextTitle || talkData?.title || "";
    const rawAbstract =
      (talkData &&
        (talkData.abstract || talkData.description || talkData.content)) ||
      btn.dataset.abstract ||
      "";
    const plainAbstract = convertAbstractToPlainText(rawAbstract);

    if (plainTextTitle && plainAbstract) {
      shareText = `${plainTextTitle}\n\n${plainAbstract}`;
    } else {
      shareText = plainTextTitle || plainAbstract;
    }
  } else if (route === "author") {
    if (!plainTextTitle) {
      const author =
        (authorIndex || {})[id] ||
        Object.values(authorIndex || {}).find(
          (a) => String(a?.person_id || a?.id) === String(id),
        );
      plainTextTitle = author
        ? `${author.firstName || author.name || ""} ${author.familyName || ""}`.trim()
        : "";
    }
    shareText = plainTextTitle;
  } else {
    shareText = plainTextTitle;
  }

  const shareUrl = `${window.location.origin}${window.location.pathname}#/${route}/${id}`;
  const fullSharePayloadText = shareText
    ? `${shareText}\n\n${shareUrl}`
    : shareUrl;

  const shareData = {
    title: plainTextTitle || "Advanced Accelerator Concepts 2026",
    text: shareText,
  };

  try {
    const parsedUrl = new URL(shareUrl, window.location.href);
    if (parsedUrl.protocol === "http:" || parsedUrl.protocol === "https:") {
      shareData.url = parsedUrl.href;
    } else {
      shareData.text = fullSharePayloadText;
    }
  } catch (err) {
    shareData.text = fullSharePayloadText;
  }

  if (navigator.share) {
    try {
      await navigator.share(shareData);
    } catch (err) {
      if (err.name !== "AbortError") {
        console.error("Web Share failed, attempting clipboard fallback:", err);
        await copyToClipboardFallback(fullSharePayloadText, btn);
      }
    }
  } else {
    await copyToClipboardFallback(fullSharePayloadText, btn);
  }
});
